/* From Uiverse.io by Harsha2lucky - Tags: flat design, neumorphism, sign-in, form, sign-up, light&dark */
.__UIV_SCOPE__ .content {
  width: 330px;
  padding: 40px 30px;
  background: #dde1e7;
  border-radius: 10px;
  box-shadow: -3px -3px 7px #ffffff73,
               2px 2px 5px rgba(94,104,121,0.288);
}

.__UIV_SCOPE__ .content .text {
  font-size: 33px;
  font-weight: 600;
  margin-bottom: 35px;
  color: #595959;
}

.__UIV_SCOPE__ .field {
  height: 50px;
  width: 100%;
  display: flex;
  position: relative;
}

.__UIV_SCOPE__ .field:nth-child(2) {
  margin-top: 20px;
}

.__UIV_SCOPE__ .field .input {
  height: 100%;
  width: 100%;
  padding-left: 45px;
  outline: none;
  border: none;
  font-size: 18px;
  background: #dde1e7;
  color: #595959;
  border-radius: 25px;
  box-shadow: inset 2px 2px 5px #BABECC,
              inset -5px -5px 10px #ffffff73;
}

.__UIV_SCOPE__ .field .input:focus {
  box-shadow: inset 1px 1px 2px #BABECC,
              inset -1px -1px 2px #ffffff73;
}

.__UIV_SCOPE__ .field .span {
  position: absolute;
  color: #595959;
  width: 50px;
  line-height: 55px;
}

.__UIV_SCOPE__ .field .label {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: 45px;
  pointer-events: none;
  color: #666666;
}

.__UIV_SCOPE__ .field .input:valid ~ label {
  opacity: 0;
}

.__UIV_SCOPE__ .forgot-pass {
  text-align: left;
  margin: 10px 0 10px 5px;
}

.__UIV_SCOPE__ .forgot-pass a {
  font-size: 16px;
  color: #666666;
  text-decoration: none;
}

.__UIV_SCOPE__ .forgot-pass:hover a {
  text-decoration: underline;
}

.__UIV_SCOPE__ .button {
  margin: 15px 0;
  width: 100%;
  height: 50px;
  font-size: 18px;
  line-height: 50px;
  font-weight: 600;
  background: #dde1e7;
  border-radius: 25px;
  border: none;
  outline: none;
  cursor: pointer;
  color: #595959;
  box-shadow: 2px 2px 5px #BABECC,
             -5px -5px 10px #ffffff73;
}

.__UIV_SCOPE__ .button:focus {
  color: #3498db;
  box-shadow: inset 2px 2px 5px #BABECC,
             inset -5px -5px 10px #ffffff73;
}

.__UIV_SCOPE__ .sign-up {
  margin: 10px 0;
  color: #595959;
  font-size: 16px;
}

.__UIV_SCOPE__ .sign-up a {
  color: #3498db;
  text-decoration: none;
}

.__UIV_SCOPE__ .sign-up a:hover {
  text-decoration: underline;
}
